// Every relative import in the repo that resolves to nothing — the shape a rename
// sweep leaves behind when a later commit adds a reference at the old path.
import { execSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
const files = execSync('git ls-files', { encoding: 'utf8' }).split('\n').filter((f) => f.endsWith('.mjs'));
const RE = /(?:^\s*(?:import|export)\b[\s\S]*?\bfrom\s*|(?:^|[^.\w])import\s*\(\s*)(['"])([^'"]+)\1/gm;
let bad = 0;
for (const f of files) {
  let src; try { src = readFileSync(f, 'utf8'); } catch { continue; }
  RE.lastIndex = 0; let m;
  while ((m = RE.exec(src))) {
    const spec = m[2];
    if (!spec.startsWith('.')) continue;
    const target = path.normalize(path.join(path.dirname(f), spec));
    if (!existsSync(target)) { console.log(`${f} -> ${spec}`); bad += 1; }
  }
}
console.log(bad ? `\n${bad} dangling` : 'no dangling imports');
EOF
