// Rewrite each shared-code/* from `export *` to the NAMED exports its consumers
// actually take, so the published surface is what is used rather than whole modules.
import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const ROOT = '/home/user/Claudinite';
const PACK = 'packs/claudinite-tasks/';
const SHARED = PACK + 'shared-code/';
const files = execSync('git ls-files', { cwd: ROOT, encoding: 'utf8' }).split('\n').filter((f) => f.endsWith('.mjs'));

// --- demand: every name any consumer takes out of a shared-code module ----------
const IMP = /(?:^\s*import\s+(?<n>\{[^}]*\}|\*\s+as\s+(?<ns>\w+)|\w+)\s+from\s*|^\s*export\s+(?<r>\{[^}]*\}|\*)\s+from\s*)(['"])(?<s>[^'"]+)\4/gms;
const demand = new Map();
for (const f of files) {
  const src = readFileSync(path.join(ROOT, f), 'utf8');
  IMP.lastIndex = 0; let m;
  while ((m = IMP.exec(src))) {
    const { n, ns, r, s } = m.groups;
    if (!s.startsWith('.')) continue;
    const t = path.posix.normalize(path.posix.join(path.posix.dirname(f), s));
    if (!t.startsWith(SHARED)) continue;
    const key = t.slice(SHARED.length);
    if (!demand.has(key)) demand.set(key, new Set());
    const set = demand.get(key);
    const clause = n ?? r;
    if (ns) {                                   // namespace import: whatever it dots off
      for (const mm of src.matchAll(new RegExp(`${ns}\\.([A-Za-z_$][\\w$]*)`, 'g'))) set.add(mm[1]);
    } else if (clause?.startsWith('{')) {
      for (const x of clause.slice(1, -1).split(',')) {
        const name = x.trim().split(/\s+as\s+/)[0].trim();
        if (name) set.add(name);
      }
    } else if (clause === '*') set.add('*');
  }
}

// --- supply: which module behind each shared-code file defines each name --------
const out = [];
for (const f of files.filter((x) => x.startsWith(SHARED))) {
  const name = f.slice(SHARED.length);
  const src = readFileSync(path.join(ROOT, f), 'utf8');
  const want = demand.get(name);
  if (!want || want.has('*')) { out.push([name, null, 'namespace/star consumer — left as is']); continue; }
  const sources = [...src.matchAll(/^export\s+\*\s+from\s+'([^']+)';$/gm)].map((m) => m[1]);
  if (!sources.length) { out.push([name, null, 'already named']); continue; }
  const resolved = [];
  for (const s of sources) {
    const abs = path.join(ROOT, path.dirname(f), s);
    const mod = await import(abs);
    resolved.push([s, new Set(Object.keys(mod))]);
  }
  const groups = new Map(sources.map((s) => [s, []]));
  const unresolved = [];
  for (const w of [...want].sort()) {
    const hit = resolved.find(([, names]) => names.has(w));
    if (hit) groups.get(hit[0]).push(w); else unresolved.push(w);
  }
  out.push([name, { groups, unresolved, sources }, '']);
}
for (const [n, plan, note] of out) {
  if (!plan) { console.log(`${n}: ${note}`); continue; }
  console.log(`\n${n}${plan.unresolved.length ? `   !! unresolved: ${plan.unresolved.join(', ')}` : ''}`);
  for (const [s, names] of plan.groups) console.log(`   ${s}  ->  ${names.length ? names.join(', ') : '(nothing consumed)'}`);
}
EOF
