// without a Node built-in, so a browser bundle can load it.
export * from '../src/contract/task-declaration-text.mjs';
export * from '../src/contract/task-defaults.mjs';
##### preconditions.mjs
// The precondition engine, published for other packs: the term vocabulary, the
// expression grammar, and the one seam that turns a discovered task plus its
// collected signals into a verdict — the same call the executor makes at pick.
export * from '../src/contract/precondition-policy.mjs';
export { loadTaskTerms, TASK_TERMS_FILE } from '../src/contract/task-terms.mjs';
export { evaluatePrecondition } from '../src/contract/precondition.mjs';
##### task-contract.mjs
// Task-declaration validation, published for other packs: the contract a
// `tasks/<name>/task.json` is held to, so a pack's own tests can exercise its task
// declarations against the same rules the scheduler applies.
export * from '../src/contract/task-contract.mjs';

// Running a declaration's precondition the way the executor does, so a pack's tests
// can assert its own tasks' decisions against the real evaluator.
export { evaluatePrecondition } from '../src/contract/precondition.mjs';

