// Demand including DYNAMIC imports: `const { a, b } = await import('…/shared-code/x')`
// is a consumer exactly as a static import is, and a surface narrowed without them
// drops names nothing static ever named.
import { execSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';
const ROOT = '/home/user/Claudinite';
const SHARED = 'packs/claudinite-tasks/shared-code/';
const DYN = /(?:const|let|var)\s*\{([^}]*)\}\s*=\s*await\s+import\s*\(\s*(['"])([^'"]+)\2\s*\)/gms;
const files = execSync('git ls-files', { cwd: ROOT, encoding: 'utf8' }).split('\n').filter((f) => f.endsWith('.mjs'));
const demand = new Map();
for (const f of files) {
  const src = readFileSync(path.join(ROOT, f), 'utf8');
  DYN.lastIndex = 0; let m;
  while ((m = DYN.exec(src))) {
    const t = path.posix.normalize(path.posix.join(path.posix.dirname(f), m[3]));
    if (!t.startsWith(SHARED)) continue;
    const key = t.slice(SHARED.length);
    if (!demand.has(key)) demand.set(key, new Set());
    for (const x of m[1].split(',')) {
      const n = x.trim().split(':')[0].trim();
      if (n) demand.get(key).add(n);
    }
  }
}
for (const [mod, names] of [...demand].sort()) {
  const have = new Set(Object.keys(await import(path.join(ROOT, SHARED, mod))));
  const missing = [...names].filter((n) => !have.has(n));
  console.log(`${mod}: dynamic consumers take ${[...names].sort().join(', ')}`);
  if (missing.length) console.log(`   !! NOT PUBLISHED: ${missing.join(', ')}`);
}
